/**
 * Official Apple Root CA Certificates (DER encoded in base64)
 * Source: https://www.apple.com/certificateauthority/
 * Used by @apple/app-store-server-library SignedDataVerifier to verify StoreKit 2 JWS signatures.
 */

export const APPLE_ROOT_CA_G3_B64 = "";
export const APPLE_ROOT_CA_G2_B64 = "";

export function getAppleRootCertificates(): Buffer[] {
  return [
    Buffer.from(APPLE_ROOT_CA_G3_B64, "base64"),
    Buffer.from(APPLE_ROOT_CA_G2_B64, "base64")
  ];
}
